using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using Petrichor.Core;using Windows.UI.Xaml;using Windows.UI.Xaml.Controls;using Windows.UI.Xaml.Navigation;using Windows.Storage;namespace Petrichor.App.Pages {public sealed partial class SettingsPage : MusicPage {public SettingsPage(){InitializeComponent();}
private bool ready;
protected override async Task LoadAsync(object p){Quality.SelectedIndex=App.Playback.Quality==AudioQuality.VeryHigh?2:App.Playback.Quality==AudioQuality.High?1:0;Repeat.SelectedIndex=(int)App.Playback.Queue.Repeat;Shuffle.IsOn=App.Playback.Queue.Shuffle;Sleep.SelectedIndex=0;ready=true;await UpdateCacheAsync();}
private async Task UpdateCacheAsync(){var bytes=await App.Offline.CacheSizeAsync();CacheStatus.Text=(bytes/1048576d).ToString("0.0")+" MB";} private async void ClearCacheClick(object s,RoutedEventArgs e)=>await ExecuteAsync(async()=>{await App.Offline.ClearCacheAsync();await UpdateCacheAsync();Shell.Current.Notify("缓存已清理。");}); private void QualityChanged(object s,SelectionChangedEventArgs e){if(!ready)return;App.Playback.Quality=Quality.SelectedIndex==2?AudioQuality.VeryHigh:Quality.SelectedIndex==1?AudioQuality.High:AudioQuality.Standard;ApplicationData.Current.LocalSettings.Values["quality"]=(int)App.Playback.Quality;}
private void RepeatChanged(object s,SelectionChangedEventArgs e){if(ready){App.Playback.Queue.Repeat=(RepeatMode)Repeat.SelectedIndex;ApplicationData.Current.LocalSettings.Values["repeat"]=Repeat.SelectedIndex;}}
private void ShuffleChanged(object s,RoutedEventArgs e){if(ready){App.Playback.Queue.Shuffle=Shuffle.IsOn;ApplicationData.Current.LocalSettings.Values["shuffle"]=Shuffle.IsOn;}}
private void SleepChanged(object s,SelectionChangedEventArgs e){if(!ready)return;int[] minutes={0,15,30,60};int n=minutes[Math.Max(0,Sleep.SelectedIndex)];App.Playback.SetSleepTimer(n==0?(TimeSpan?)null:TimeSpan.FromMinutes(n));Shell.Current.Notify(n==0?"已关闭睡眠定时。":n+" 分钟后暂停播放。");}}}

